def shortest_path(graph: dict[str, list[tuple[str, float]]], start: str, end: str) -> tuple[float, list[str]]:
    """
    Implements Dijkstra's algorithm to find the shortest path between two nodes in a weighted directed graph.
    """
    # Priority queue to store the nodes to explore
    queue = []
    heapq.heappush(queue, (0, start))  # (distance, node)

    # Distances dictionary to track the shortest distance to each node
    distances = {node: float('inf') for node in graph}
    distances[start] = 0

    # Parent dictionary to reconstruct the path
    parents = {node: None for node in graph}

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        if current_node == end:
            # Path has been found, reconstruct the path
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = parents[current_node]
            return (current_distance, path[::-1])

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                parents[neighbor] = current_node
                heapq.heappush(queue, (distance, neighbor))

    return (float('inf'), [])

